1172	/**
1173	 * Builds the declarative route table consumed by {@link dispatchRoute}.
1174	 *
1175	 * All closure variables required by route handlers (`ledgerRoot`, `configPath`,
1176	 * `orchestratorLogsDir`, `bootVersions`) are captured via the domain sub-builder
1177	 * functions. Each sub-builder owns a single domain area and accepts only the
1178	 * closure parameters it needs:
1179	 *
1180	 *   - {@link buildConfigRoutes}      — `PUT/GET /api/config`, `GET /api/server-info`
1181	 *   - {@link buildOrchestratorRoutes} — `/api/orchestrator/*`
1182	 *   - {@link buildRepoRoutes}         — `/api/repos/*`
1183	 *   - {@link buildKnowledgeRoutes}    — `/api/knowledge/*`
1184	 *   - {@link buildModelRoutes}        — `/api/models/*`, `/api/model-assignments/*`, `/api/personas/*`
1185	 *   - {@link buildProjectRoutes}      — `/api/projects/*`, `/api/insights`
1186	 *
1187	 * The composed array preserves the Section A/B/C ordering invariant:
1188	 *
1189	 *   Section A — Body-parsing routes (no `noBody` flag). Sub-builders place their
1190	 *               Section A entries first; buildRoutes spreads them in domain order.
1191	 *
1192	 *   Section B — Keyword-specific body-free routes (`noBody: true`). Routes with
1193	 *               a fixed keyword suffix (e.g. `/plan`, `/archive`) are more specific
1194	 *               than the Section C catch-alls and MUST precede them.
1195	 *
1196	 *   Section C — Catch-all body-free routes. These are placed last by
1197	 *               {@link buildProjectRoutes} and are spread last.
1198	 *
1199	 * ⚠️  ORDERING CONSTRAINT (load-bearing, not cosmetic):
1200	 *     Section B MUST precede Section C across all sub-builders. The dispatcher
1201	 *     walks the table in declaration order and returns on the first match. A
1202	 *     Section C catch-all such as `GET /api/projects/:repo/:slug` would silently
1203	 *     shadow all deprecated Section B keyword routes (`/:slug/plan`,
1204	 *     `/:slug/synthesis`, etc.) if they were declared before them, permanently
1205	 *     breaking backward compatibility with pre-namespace clients.
1206	 */
1207	export function buildRoutes(
1208	  ledgerRoot: string,
1209	  configPath: string,
1210	  orchestratorLogsDir: string,
1211	  bootVersions: WorkspaceVersions | null
1212	): Route[] {
1213	  return [
1214	    ...buildConfigRoutes(configPath, bootVersions),
1215	    ...buildOrchestratorRoutes(ledgerRoot, orchestratorLogsDir),
1216	    ...buildRepoRoutes(ledgerRoot),
1217	    ...buildKnowledgeRoutes(ledgerRoot),
1218	    ...buildModelRoutes(),
1219	    ...buildProjectRoutes(ledgerRoot, orchestratorLogsDir),
1220	  ];
1221	}
1222	
1223	/**
1224	 * Returns the full route table using sentinel dummy arguments, without
1225	 * requiring callers to supply real filesystem paths.
1226	 *
1227	 * Intended for structural tests (e.g. `route-table.test.ts`) that inspect the
1228	 * route table shape — method validity, named-capture-group compliance,
1229	 * duplicate detection — without executing any handlers.
1230	 *
1231	 * Uses `/dev/null` as a safe sentinel for all path arguments and `null` for
1232	 * `bootVersions`. The handlers captured inside each route are closures over
1233	 * these sentinels; as long as no handler is actually invoked the sentinels have
1234	 * no observable effect.
1235	 *
1236	 * @returns The full `Route[]` table, identical in structure to what
1237	 *   {@link handleRequest} uses at runtime.
1238	 */
1239	export function getRouteDescriptors(): Route[] {
1240	  return buildRoutes('/dev/null', '/dev/null', '/dev/null', null);
1241	}
1242	
1243	/**
1244	 * Iterates the route table, matches the request, conditionally parses the body,
1245	 * invokes the handler, and writes the response.
1246	 *
1247	 * Parses query parameters from the full `url` (including query string) via
1248	 * {@link parseQueryString} and passes the resulting `URLSearchParams` as the
1249	 * third argument to the matched handler.
1250	 *
1251	 * Returns `true` if a route was matched (caller should return immediately),
1252	 * or `false` if no route matched (caller should fall through).
1253	 */
1254	export async function dispatchRoute(
1255	  req: IncomingMessage,
1256	  res: ServerResponse,
1257	  method: string,
1258	  url: string,
1259	  port: number,
1260	  routes: Route[]
1261	): Promise<boolean> {
1262	  const [path] = url.split('?') as [string];
1263	  const query = parseQueryString(url);
1264	  for (const route of routes) {
1265	    if (route.method !== method) continue;
1266	    let groups: Record<string, string> | undefined;
1267	    if (typeof route.path === 'string') {
1268	      if (route.path !== path) continue;
1269	    } else {
1270	      const m = route.path.exec(path);
1271	      if (!m) continue;
1272	      groups = (m.groups ?? {}) as Record<string, string>;
1273	    }
1274	    try {
1275	      const body = route.noBody ? undefined : await readJsonBody(req);
1276	      const result = await route.handler(body, groups, query);
1277	      if (route.statusCode === 204) {
1278	        res.writeHead(204, { ...corsHeaders(port), ...securityHeaders() });
1279	        res.end();
1280	      } else {
1281	        sendJson(res, route.statusCode ?? 200, result, port);
1282	      }
1283	    } catch (err) {
1284	      if (err instanceof PayloadTooLargeError) {
1285	        sendError(res, 413, 'PAYLOAD_TOO_LARGE', 'Payload Too Large.', port);
1286	      } else if (err instanceof ApiError) {
1287	        sendError(res, apiErrorToStatus(err.code), err.code, err.message, port);
1288	      } else {
1289	        process.stderr.write(
1290	          `[server] Unhandled error in ${method} ${path}: ${String(err)}\n`
1291	        );
1292	        sendError(res, 500, 'INTERNAL_ERROR', 'An unexpected error occurred.', port);
1293	      }
1294	    }
1295	    return true;
1296	  }
1297	  return false;
1298	}
